/// <summary>
/// Extension of <c>PurchLineType</c> class to add custom initialization logic for AVARUMPointOutBBDateId.
/// </summary>
[ExtensionOf(ClassStr(PurchLineType))]
final class AVARUMPurchLineTypeCls_Extension
{
}

Method.Source:
/// <summary>
/// Initializes fields from <c>InventTable</c> on the purchase line, including custom AVARUMPointOutBBDateId.
/// </summary>
/// <param name="_inventTable">The <c>InventTable</c> record to initialize from.</param>
/// <param name="_searchPrice">Indicates whether to search for price.</param>
/// <param name="_setAddressFromInventDim">Indicates whether to set address from inventory dimension.</param>
/// <param name="_initDateFields">Indicates whether to initialize date fields.</param>
/// <param name="_executeOnlyIfProductIsFullySpecified">Indicates whether to execute only if product is fully specified.</param>
public void initFromInventTable
(
    InventTable _inventTable,
    boolean _searchPrice,
    boolean _setAddressFromInventDim,
    boolean _initDateFields,
    boolean _executeOnlyIfProductIsFullySpecified
)
{
    // Call the next method in the extension chain.
    next initFromInventTable(_inventTable, _searchPrice, _setAddressFromInventDim, _initDateFields, _executeOnlyIfProductIsFullySpecified);

    // Set the custom fields from InventTable.
    purchLine.AVARUMPrintBBDate = _inventTable.AVARUMPrintBBDate;
}
